    ]
  },
  {
    "alert_id": "ALERT_002",
    "title": "Rising creatinine trend over 6 years while on TDF",
    "message": "Guidelines require annual serum creatinine and eGFR monitoring for patients on TDF. Patient's creatinine has progressively risen from 0.9 (2020) to 1.0 (2021), 1.1 (2022), 1.2 (2023), and now 1.4 (2026), with eGFR declining to 52. This consistent upward trend signals ongoing renal injury even if each individual increment seemed modest. The latest value alone triggers the TDF contraindication threshold (GFR <60). The 3-year gap between 2023 and 2026 labs also exceeds the recommended 12-month monitoring interval, meaning renal decline went undetected for an extended period.",
    "issue_type": "monitoring_gap",
    "severity": "high",
    "recommended_action": "Ensure creatinine and eGFR are checked at least every 12 months on TDF. Given current eGFR 52, switch TDF to TAF and escalate renal monitoring to every 3-6 months.",
    "citations": [
      {"page_number": 29, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__p29_c1"},
      {"page_number": 10, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__p10_c1"}
    ]
  },
  {
    "alert_id": "ALERT_003",
    "title": "No clinician assessment or plan documented",
    "message": "No assessment or plan was documented for this visit despite significant findings requiring action. The patient has eGFR 52 (below the TDF contraindication threshold of 60), a 6-year creatinine rising trend, proteinuria, and mild fatigue potentially related to renal dysfunction or TDF toxicity. Guidelines require screening for developing signs and symptoms at every visit and appropriate laboratory monitoring for patients on TDF. The absence of a documented plan means these abnormalities are not being addressed, risking further renal damage.",
    "issue_type": "plan_review",
    "severity": "high",
    "recommended_action": "Document assessment addressing eGFR 52, creatinine trend, and proteinuria. Plan should include TDF-to-TAF switch, renal referral, and repeat renal function tests.",
    "citations": [
      {"page_number": 29, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__p29_c1"},
      {"page_number": 10, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__p10_c1"}
    ]
  },
  {
    "alert_id": "ALERT_004",
    "title": "Fatigue and proteinuria may indicate TDF renal toxicity",
    "message": "Guidelines list exhaustion or extreme fatigue, change in urine volume, and muscle cramps as presenting signs of TDF toxicity requiring LFTs and RFTs. Patient reports mild fatigue for 2 months and urinalysis shows protein 1+. Evidence for TDF attribution: fatigue and proteinuria are recognized TDF toxicity manifestations, and the patient has concurrent eGFR decline to 52. Evidence against: fatigue is non-specific and the patient attributes it to work schedule; proteinuria could have other causes. The combination of fatigue, proteinuria, and declining eGFR together is more concerning than any finding alone and warrants evaluation for Fanconi syndrome.",
    "issue_type": "toxicity",
    "severity": "high",
    "recommended_action": "Evaluate for TDF-related renal toxicity including fractional phosphate excretion, urine glucose, and serum phosphate. If confirmed, switch TDF to TAF.",
